insert into public.zenad_advertisers(id,name,status) values('00000000-0000-0000-0000-000000000001','Testagram House Ads','active') on conflict(id) do update set name=excluded.name,status='active';
insert into public.zenad_campaigns(id,advertiser_id,name,status,priority,bid_cpm_micros,targeting) values('00000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000001','Testagram Platform House Campaign','active',100,1000000,'{"countries":[],"devices":[],"genres":[],"keywords":[],"segments":[],"frequencyCap":{"maxImpressions":3,"windowHours":24}}'::jsonb) on conflict(id) do update set status='active',priority=100,bid_cpm_micros=1000000,targeting=excluded.targeting;
insert into public.zenad_campaign_apps(campaign_id,app_id) values('00000000-0000-0000-0000-000000000001','testagram') on conflict do nothing;
insert into public.zenad_creatives(id,campaign_id,format,headline,body,cta,click_through_url,weight,enabled) values('00000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000001','display','Advertise on Testagram','Reach people where conversations happen. Create your first Testagram campaign.','Get started','https://testagram.site/admin/ad-config',1,true) on conflict(id) do update set headline=excluded.headline,body=excluded.body,cta=excluded.cta,click_through_url=excluded.click_through_url,enabled=true;
